import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Contributing to pumpkin-plugins","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/CONTRIBUTING.md"},"headers":[],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md","lastUpdated":1792252051000}`),a={name:`CONTRIBUTING.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="contributing-to-pumpkin-plugins" tabindex="-1">Contributing to <code>pumpkin-plugins</code> <a class="header-anchor" href="#contributing-to-pumpkin-plugins" aria-label="Permalink to “Contributing to pumpkin-plugins”">​</a></h1><p>These steps take you from setting up the repository to opening a pull request.</p><h2 id="get-set-up" tabindex="-1">Get set up <a class="header-anchor" href="#get-set-up" aria-label="Permalink to “Get set up”">​</a></h2><p>Use the Node version in <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.node-version" target="_blank" rel="noreferrer"><code>.node-version</code></a> and the pnpm version declared in <a href="package.json"><code>package.json</code></a> so your tools match the project. Then install the workspace:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>If you&#39;re creating a plugin, action, or extension, use its generator: <a href="/pumpkin-plugins/guides/creating-a-plugin"><code>pnpm gen</code></a>, <a href="/pumpkin-plugins/guides/creating-an-action"><code>pnpm gen:action</code></a>, or <a href="/pumpkin-plugins/guides/creating-an-extension"><code>pnpm gen:extension</code></a>. For an existing component, start with the relevant guide in <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/docs/README.md" target="_blank" rel="noreferrer"><code>docs/</code></a>.</p><h2 id="make-and-check-your-change" tabindex="-1">Make and check your change <a class="header-anchor" href="#make-and-check-your-change" aria-label="Permalink to “Make and check your change”">​</a></h2><p>Follow the repository&#39;s <a href="/pumpkin-plugins/guides/code-style">code style</a>. Keep unit tests beside the code. Put integration tests that need a real Pumpkin server in the package&#39;s <code>test/</code> directory; the <a href="/pumpkin-plugins/guides/testing">Testing guide</a> explains how to run them.</p><p>Update the docs and READMEs that describe your change. If you change generated README content, edit its source and run <code>pnpm readme</code>; then run <code>pnpm readme:check</code> to confirm the generated content is up to date.</p><p>Run the checks that cover the areas you changed:</p><ul><li>For code changes, run <code>pnpm lint</code>, <code>pnpm typecheck</code>, and <code>pnpm test</code>.</li><li>For repository metadata and docs, run <code>pnpm check</code>.</li><li>For plugin runtime changes, run the affected package&#39;s integration tests against a real Pumpkin server. The <a href="/pumpkin-plugins/guides/testing">Testing guide</a> gives you the scoped command.</li></ul><h2 id="open-a-pull-request" tabindex="-1">Open a pull request <a class="header-anchor" href="#open-a-pull-request" aria-label="Permalink to “Open a pull request”">​</a></h2><p>Open your PR against the current <code>master</code> branch and keep it focused on one topic. Explain what changed and why, list the checks and scenarios you ran, and mention any checks you skipped or that failed. If you ran integration tests, include the Pumpkin version. The <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.github/pull_request_template.md" target="_blank" rel="noreferrer">pull request template</a> has the full checklist.</p><p>Use Conventional Commit messages such as <code>feat:</code>, <code>fix:</code>, or <code>docs:</code>. Pull requests are rebase-merged, so each commit lands on <code>master</code> with its original message; see <a href="/pumpkin-plugins/guides/ci-and-releases#merging">CI and releases</a>. The template&#39;s AI-assisted field is collected for analytics only, and you&#39;re responsible for everything in your PR.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};